function Title({ text }) {
  // Attempting to change a prop directly
  if (!text) {
    text = 'Untitled';   // mutating props is not allowed
  }
  return <h2 style={{ fontFamily: 'system-ui' }}>{text}</h2>;
}

function App() {
  return (
    <div style={{ padding: 16 }}>
      <Title text="" />
    </div>
  );
}

solution.code:
function Title({ text = 'Untitled' }) {
  const display = text || 'Untitled';
  return <h2 style={{ fontFamily: 'system-ui' }}>{display}</h2>;
}

function App() {
  return (
    <div style={{ padding: 16 }}>
      <Title text="" />
    </div>
  );
}

function Button({ label, onClick, disabled = false }) {
  return (
    <button onClick={onClick} disabled={disabled} style={{ fontFamily: 'system-ui', padding: '6px 12px' }}>
      {label}
    </button>
  );
}

function App() {
  return (
    <div style={{ padding: 16 }}>
      <Button label="Save" onClick={() => alert('Saved!')} />
      <Button label="Disabled" onClick={() => {}} disabled />
    </div>
  );
}
